	const url = `${SIM_ORIGIN}/#/simulation?handoff=${nonce}&from=${encodeURIComponent(window.location.origin)}`;
	let popup = null;
	try { popup = window.open(url, '_blank'); } catch (e) { popup = null; }
	if (!popup) { return false; }
